package com.xqfx.requirements.requirement;
import java.time.LocalDate;
record RequirementResponse(Long id,String requesterName,String department,String title,RequirementType type,String content,Long systemId,RequirementSaveType saveType,RequirementStatus status,Long targetVersionId,LocalDate periodStartDate,LocalDate periodEndDate){static RequirementResponse from(RequirementEntity r){return new RequirementResponse(r.id(),r.requesterName(),r.department(),r.title(),r.type(),r.content(),r.system()==null?null:r.system().id(),r.saveType(),r.status(),r.targetVersion()==null?null:r.targetVersion().id(),r.periodStartDate(),r.periodEndDate());}}
